async function processSelectedFiles(mode) {
  var input = document.getElementById("file");
  var files = input.files ? Array.from(input.files) : [];
  if (!files.length) return setStatus("\u8BF7\u9009\u62E9\u6587\u4EF6", "err");
  if (mode === "cache" || !lanOk) {
    for (var i = 0; i < files.length; i++) {
      var f = files[i];
      var b64 = await blobToBase64(f);
      await addQueueItem({
        type: "file",
        fileName: f.name,
        mimeType: f.type || "application/octet-stream",
        fileBase64: b64,
        title: f.name,
        size: f.size,
        organize: mode !== "inbox",
        targetLabel: mode === "inbox" ? "\u4EC5\u6536\u4EF6\u7BB1\uFF08\u53EA\u5B58\u8BF4\u660E\uFF09" : undefined,
      });
    }
    input.value = "";
    setStatus((!lanOk && mode !== "cache" ? "\u672A\u8FDE\u5C40\u57DF\u7F51\uFF0C\u5DF2\u7F13\u5B58 " : "\u5DF2\u7F13\u5B58 ") + files.length + " \u4E2A\u6587\u4EF6", !lanOk && mode !== "cache" ? "err" : "ok");
    return;
  }
  setStatus("\u53D1\u9001\u6587\u4EF6\u4E2D\u2026");
  var ok = 0, fail = 0;
  for (var j = 0; j < files.length; j++) {
    try {
      var ff = files[j];
      var bb = await blobToBase64(ff);
      await api("/api/file", {
        fileBase64: bb,
        fileName: ff.name,
        mimeType: ff.type || "application/octet-stream",
        title: ff.name,
        organize: mode === "inbox" ? false : true,
        notebook_id: selectedNb,
        item_id: selectedItem || "",
        capturedAt: Date.now(),
      });
      ok++;
    } catch (e) {
      fail++;
      try {
        var f2 = files[j];
        var b2 = await blobToBase64(f2);
        await addQueueItem({
          type: "file",
          fileName: f2.name,
          mimeType: f2.type || "application/octet-stream",
          fileBase64: b2,
          title: f2.name,
          size: f2.size,
          organize: mode === "inbox" ? false : true,
          targetLabel: mode === "inbox" ? "\u4EC5\u6536\u4EF6\u7BB1\uFF08\u53EA\u5B58\u8BF4\u660E\uFF09" : undefined,
        });
      } catch (e2) {}
    }
  }
  input.value = "";
  setStatus("\u6587\u4EF6\u5B8C\u6210\uFF1A\u6210\u529F " + ok + (fail ? "\uFF0C\u5931\u8D25\u5E76\u5DF2\u7F13\u5B58 " + fail : ""), ok ? "ok" : "err");
  refreshRecent();
}

